-- Rifts World Book 8: Japan - magic gear (printed 32-43): 63 new rows.
-- See apps/character-creator/docs/surveys/japan.md, extraction plan step 2.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-a-japan-magic-gear.sql
--
-- TEXT LAYER, page_offset +1. Extracted by two book-extract-workers
-- (printed 32-37 and 37-43) and checked row by row by book-reconcile.
--
-- WHAT IS HERE (5 armor, 33 magic, 25 weapon):
--   printed 32-33  the Millennium Tree's gifts that a character can own - bark
--                  body armor, the bark shield in its three printed sizes, leaf
--                  body armor and the leaf blanket of healing. The survey filed
--                  these pages as "the tree's own powers"; the TREE's powers
--                  (camouflage, weather and ley line control, teleportation,
--                  healing, purification, resurrection, sixth sense, visions)
--                  are still left out, but these four are items with prices.
--   printed 33-37  8 wands, 8 staves, the corrupted wand or staff, and the two
--                  weapons of wood (javelin, throwing stick).
--   printed 37-39  enchanted weapons, one row per priced variant: 5 elemental
--                  shuriken, 4 magic powder grenades, 4 singing arrows, 2 Zen
--                  Master's bows.
--   printed 39-40  the three Greater Daisho rune swords.
--   printed 40-43  magical items, the purse in its three kinds and the kami
--                  statue in its four sizes.
--
-- PRICES. cost is the LOW end of a printed range and cost_note the range, as
-- elsewhere in the catalog. The wands and staves print one price for all
-- (printed 34: wand 100,000-200,000, staff 250,000-500,000) and each row takes
-- it. The Greater Daisho print only a set price "in excess of 400 million" and
-- the Ghostly Katana none, so all three store NULL with the wording in
-- cost_note - an unpriced item is a finished row (schema.sql, gear.cost).
--
-- M.D.C. printed as dice (a wand's 1D4x100, a statue's 3D6x10) cannot go in the
-- integer mdc column and is stated in the description instead.
--
-- Categories follow Atlantis's rune weapons: a weapon is 'weapon', armor and
-- shields 'armor', every other enchanted object 'magic'.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('wand-of-the-animal', 'Wand of the Animal', 'rifts', 'magic', NULL, 100000, 'Rarely sold, and wands are extremely rare for everybody. A wand fetches 100,000 to 200,000 credits (printed 34).', '1D4 S.D.C.; M.D. to vampires', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree wand (printed 33-34): 1-3 ft; 1D4x100 M.D.C. and 1D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. As a weapon 1D4 S.D.C., M.D. to vampires. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. Constant power: climb 90%/75%. Five spells a day in any mix: eyes of the wolf, swim as a fish (superior), superhuman strength, metamorphosis: animal. Spell strength 7th level.', 'Rifts World Book 8: Japan p.34'),
('wand-of-deception', 'Wand of Deception', 'rifts', 'magic', NULL, 100000, 'Rarely sold, and wands are extremely rare for everybody. A wand fetches 100,000 to 200,000 credits (printed 34).', '1D4 S.D.C.; M.D. to vampires', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree wand (printed 33-34): 1-3 ft; 1D4x100 M.D.C. and 1D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. As a weapon 1D4 S.D.C., M.D. to vampires. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A short, scraggly, ordinary-looking twig. Constant power: chameleon, shared by anyone holding it. Five spells a day: death trance, fool''s gold, multiple image, mask of deceit, turn invisible (self). Spell strength 7th level.', 'Rifts World Book 8: Japan p.34'),
('wand-of-divination', 'Wand of Divination', 'rifts', 'magic', NULL, 100000, 'Rarely sold, and wands are extremely rare for everybody. A wand fetches 100,000 to 200,000 credits (printed 34).', '1D4 S.D.C.; M.D. to vampires', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree wand (printed 33-34): 1-3 ft; 1D4x100 M.D.C. and 1D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. As a weapon 1D4 S.D.C., M.D. to vampires. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A narrow pointed stick spun on the palm; where it falls answers yes, no, uncertain or probably. It stands upright for danger to the land and turns black when its parent tree is in serious danger. Reliable only on important questions of danger, death and helping others. No spells.', 'Rifts World Book 8: Japan p.34'),
('wand-of-dowsing', 'Wand of Dowsing', 'rifts', 'magic', NULL, 100000, 'Rarely sold, and wands are extremely rare for everybody. A wand fetches 100,000 to 200,000 credits (printed 34).', '1D4 S.D.C.; M.D. to vampires', 0, '300 miles (482 km)', NULL, NULL, NULL, NULL, NULL, 'Millennium Tree wand (printed 33-34): 1-3 ft; 1D4x100 M.D.C. and 1D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. As a weapon 1D4 S.D.C., M.D. to vampires. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A Y-shaped stick that points toward what is sought, then down at the spot. Constant: sense direction of travel 98% and time of day 80%, +5% tracking and wilderness survival. Dowses five times a day for water, coal, ley lines and nexuses, the nearest Millennium Tree, or home or a loved one; each lasts until found or up to 3 hours.', 'Rifts World Book 8: Japan p.34'),
('wand-of-knowledge', 'Wand of Knowledge', 'rifts', 'magic', NULL, 100000, 'Rarely sold, and wands are extremely rare for everybody. A wand fetches 100,000 to 200,000 credits (printed 34).', '1D4 S.D.C.; M.D. to vampires', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree wand (printed 33-34): 1-3 ft; 1D4x100 M.D.C. and 1D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. As a weapon 1D4 S.D.C., M.D. to vampires. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A gnarled stick with two buds at the tip. Constant power: tongues, shared by anyone holding it. Five spells a day: eyes of Thoth, words of truth, memory bank, commune with spirits. Spell strength 7th level.', 'Rifts World Book 8: Japan p.34'),
('wand-of-life', 'Wand of Life', 'rifts', 'magic', NULL, 100000, 'Rarely sold, and wands are extremely rare for everybody. A wand fetches 100,000 to 200,000 credits (printed 34).', '1D4 S.D.C.; M.D. to vampires', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree wand (printed 33-34): 1-3 ft; 1D4x100 M.D.C. and 1D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. As a weapon 1D4 S.D.C., M.D. to vampires. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A twig seldom over 12 inches, with 2D4 buds that never grow or die; the bud count is its daily uses of superior healing (1D6 hit points or S.D.C. per bud) and its daily spell casts: negate poisons, cure minor disorders, cure illness, purification of food and water, water to wine, at 7th level. The owner gets +2 to save vs poison, drugs, toxins and disease and +5% vs coma.', 'Rifts World Book 8: Japan p.35'),
('wand-of-power', 'Wand of Power', 'rifts', 'magic', NULL, 100000, 'Rarely sold, and wands are extremely rare for everybody. A wand fetches 100,000 to 200,000 credits (printed 34). Extremely rare.', '1D4 S.D.C.; M.D. to vampires', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree wand (printed 33-34): 1-3 ft; 1D4x100 M.D.C. and 1D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. As a weapon 1D4 S.D.C., M.D. to vampires. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A 2-3 ft jagged, lightning-bolt-shaped stick. Constant power: invulnerability, shared by anyone holding it. Five spells a day: energy disruption, call lightning, armor of Ithan, superhuman strength, negate magic. Spell strength 7th level.', 'Rifts World Book 8: Japan p.35'),
('wand-of-seeing', 'Wand of Seeing', 'rifts', 'magic', NULL, 100000, 'Rarely sold, and wands are extremely rare for everybody. A wand fetches 100,000 to 200,000 credits (printed 34). Extremely rare.', '1D4 S.D.C.; M.D. to vampires', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree wand (printed 33-34): 1-3 ft; 1D4x100 M.D.C. and 1D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. As a weapon 1D4 S.D.C., M.D. to vampires. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A straight 2-3 ft stick with two eye-like knots. Constant: see the invisible (shared by anyone holding it), +5% track and identify plants. Five spells a day: globe of daylight, see aura, detect concealment, eyes of Thoth, eyes of the wolf. Spell strength 7th level.', 'Rifts World Book 8: Japan p.35'),
('sohei-staff-of-defense', 'Sohei Staff of Defense', 'rifts', 'magic', NULL, 250000, 'Rarely sold. A staff fetches 250,000 to 500,000 credits (printed 34).', '2D6 S.D.C. to mortals; 3D6 M.D. to supernatural beings, +1D6 M.D. at the owner''s levels 5, 10 and 15', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree staff (printed 33-34): 4-8 ft; 2D4x100 M.D.C. and 2D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A plain 8 ft shaft, walking stick and symbol of the sohei, the simplest staff the tree gives; no constant powers or spells. Monks of 9th level or great warrior monks may be given other staves.', 'Rifts World Book 8: Japan p.35'),
('staff-of-the-earth', 'Staff of the Earth', 'rifts', 'magic', NULL, 250000, 'Rarely sold. A staff fetches 250,000 to 500,000 credits (printed 34).', '2D6 S.D.C.; 2D6 M.D. to vampires and most supernatural beings', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree staff (printed 33-34): 4-8 ft; 2D4x100 M.D.C. and 2D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A short, thick, dark brown stick. Constant: sense magic and sense ley lines as a ley line walker. Ten spells a day: chameleon, ignite fire, purify food and water, superhuman strength, repel animals, stone to flesh, turn dead, exorcism, circle of protection (simple). Spell strength 10th level.', 'Rifts World Book 8: Japan p.35'),
('staff-of-the-hunter', 'Staff of the Hunter', 'rifts', 'magic', NULL, 250000, 'Rarely sold. A staff fetches 250,000 to 500,000 credits (printed 34). Quite rare except among yamabushi.', '2D6 S.D.C. to mortals; 2D6 M.D. to mega-damage monsters and oni', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree staff (printed 33-34): 4-8 ft; 2D4x100 M.D.C. and 2D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A tall thin staff with a club-like top. Constant at 88%: identify tracks, track humanoids and animals, prepare hides, land navigation, wilderness survival. Eight spells a day: ignite fire, climb, escape, swim as a fish, befuddle, magic net. Spell strength 10th level.', 'Rifts World Book 8: Japan p.35'),
('staff-of-life', 'Staff of Life', 'rifts', 'magic', NULL, 250000, 'Rarely sold. A staff fetches 250,000 to 500,000 credits (printed 34). Quite rare except among Shinto priests.', '2D6 S.D.C.; 2D6 M.D. to vampires and most supernatural beings', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree staff (printed 33-34): 4-8 ft; 2D4x100 M.D.C. and 2D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A 6-8 ft branch with 2D4+6 undying buds; the bud count is its daily uses of superior healing (1D6 per bud) and its daily casts of globe of daylight, breathe without air, negate poisons, cure minor disorders, cure illness, purification and water to wine at 10th level. Owner +2 vs poison, drugs, toxins and disease, +5% vs coma. Restoration (reattach limbs, revive the comatose) permanently spends four buds; the staff vanishes when they are gone.', 'Rifts World Book 8: Japan p.35-36'),
('staff-of-prosperity', 'Staff of Prosperity', 'rifts', 'magic', NULL, 250000, 'Rarely sold. A staff fetches 250,000 to 500,000 credits (printed 34). Very rare outside the New Empire.', '2D6 S.D.C.; 2D6 M.D. to vampires and most supernatural beings', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree staff (printed 33-34): 4-8 ft; 2D4x100 M.D.C. and 2D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A slender golden rod wound with vine. Constant: identify plants, fruit and ingredients (poison included) by taste, +4 vs poison, +10% cooking. Planted in soil (not sand or solid rock) it makes 20,000 square feet (plus 2,000 a year for 20 years) rich and fertile, safe from blight and minor frost, yielding double crops, and no locust or frost disaster takes more than 25%; as a scarecrow''s strut it cuts pests below 10%. The land reverts if it is removed.', 'Rifts World Book 8: Japan p.36'),
('staff-of-purity', 'Staff of Purity', 'rifts', 'magic', NULL, 250000, 'Rarely sold. A staff fetches 250,000 to 500,000 credits (printed 34).', '2D6 S.D.C. to mortals; 4D6 M.D. to demons and devils; 6D6 M.D. to vampires', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree staff (printed 33-34): 4-8 ft; 2D4x100 M.D.C. and 2D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A smooth, tall white staff. Powers: purify water, swim and fish at 88%, and its holder never drowns. Placed in a well, spring or stream it keeps the water permanently clean of pollution, poison and disease, and proof against curses.', 'Rifts World Book 8: Japan p.36'),
('staff-of-the-serpent', 'Staff of the Serpent', 'rifts', 'magic', NULL, 250000, 'Rarely sold. A staff fetches 250,000 to 500,000 credits (printed 34). Quite rare except among bishamon monks.', '3D6 M.D.; 6D6 M.D. to dragons and supernatural serpents', 1, 'snake form stays within 1000 ft (305 m) of its owner', NULL, NULL, NULL, NULL, NULL, 'Millennium Tree staff (printed 33-34): 4-8 ft; 2D4x100 M.D.C. and 2D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A branch twisted like snake coils, one of the few offensive staves. Constant: see the invisible; immune to snake venom, dragon''s fire and breath and M.D. fire. Thrown down on command it becomes a mega-damage snake (150 M.D.C., horror factor 10, 4 attacks, bite 2D6 M.D. or 4D6 to dragons) that obeys simple commands, has P.S. 10 and sees the invisible.', 'Rifts World Book 8: Japan p.36'),
('staff-of-the-wind', 'Staff of the Wind', 'rifts', 'magic', NULL, 250000, 'Rarely sold. A staff fetches 250,000 to 500,000 credits (printed 34).', '2D6 S.D.C.; 2D6 M.D. to vampires and most supernatural beings', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Millennium Tree staff (printed 33-34): 4-8 ft; 2D4x100 M.D.C. and 2D4x10 P.P.E. that its owner, or a good-aligned helper he permits, may draw on; regains all lost M.D.C. and P.P.E. in 24 hours and vanishes if destroyed. Powers work only while held. Sacred to Shinto priests, yamabushi and sohei monks. A staff with an oval hole at the top and strands that always stir as if in wind. Constant: float in air (shared by anyone holding it) and sense wind direction. Ten spells a day: levitation, fuel flame, fly as the eagle, fingers of wind, call lightning, wind rush, summon fog, calm storms. Spell strength 10th level.', 'Rifts World Book 8: Japan p.36'),
('corrupted-millennium-wand-or-staff', 'Corrupted Millennium Tree Wand or Staff', 'rifts', 'magic', NULL, NULL, 'No price printed.', 'Wand 1D4 S.D.C. (1D4 M.D. to vampires); staff 3D6 M.D., double to vampires, +2D6 M.D. per low-level spell given up, to a maximum of 1D6x10', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A wand or staff purged and re-empowered by evil alchemists or bio-wizards, or taken from a tree by force: weaker than a true one and without constant powers. A wand holds up to four spells of levels 1-6, or two of 7-12, or one high and two low; a staff twice that; never spells of levels 13-15. Spell strength 3rd-5th level for a wand, 4th-7th for a staff, +2 for a truly powerful maker; casts per day fall as more spells are stored. Bio-wizards may build one into a weapon, armor or box; a wand in a weapon adds 1D6 M.D. per low-level spell, to 4D6.', 'Rifts World Book 8: Japan p.36-37'),
('millennium-vampire-slaying-javelin', 'Vampire Slaying Javelin', 'rifts', 'weapon', NULL, NULL, 'No price printed.', '1D6 S.D.C.; 4D6 M.D. to supernatural beings; 6D6 M.D. to vampires and all undead', 0, '700 ft (213 m)', NULL, NULL, NULL, NULL, NULL, 'A Millennium Tree weapon of wood made to look like a crude javelin. It flies back to its owner''s hand in about three seconds, which counts as one melee action.', 'Rifts World Book 8: Japan p.35'),
('millennium-throwing-stick', 'Throwing Stick (Millennium Tree)', 'rifts', 'weapon', NULL, NULL, 'No price printed.', '1D6 S.D.C.; 3D6 M.D. to supernatural beings; 4D6 M.D. to vampires', 0, '400 ft (122 m)', NULL, NULL, NULL, NULL, NULL, 'A Millennium Tree weapon of wood: a short flat hunting stick, rounded at one end like a boomerang, that flies back to its owner''s hand.', 'Rifts World Book 8: Japan p.35'),
('millennium-bark-body-armor', 'Bark Body Armor', 'rifts', 'armor', 15, 80000, '80,000-100,000 credits when sold. Rarely sold; a gift of the tree. Rare except among warrior monks and Shinto priests.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 120, 'Millennium Tree bark fixed to an undergarment: light mega-damage armor, typically 120 M.D.C., good mobility, -5% prowl. Holds 4D6 P.P.E. a practitioner of magic can draw on. Magic energy attacks (fire, dragon''s fire, lightning, energy blasts) do one-third damage; rune weapons, other magic weapons, conventional energy weapons and explosives do full. +1 to save vs poison, toxins, gases and disease.', 'Rifts World Book 8: Japan p.32'),
('millennium-bark-shield-small', 'Bark Shield (Small)', 'rifts', 'armor', 3, 15000, '15,000-30,000 credits when sold, any size. Rarely sold; a gift of the tree. Rare except among warrior monks and Shinto priests.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'Millennium Tree bark shield: it can parry mega-damage magic weapons, the blows of vampires and supernatural beings, and dragon''s breath and other slow or predictable attacks; a successful parry absorbs the damage.', 'Rifts World Book 8: Japan p.32'),
('millennium-bark-shield-medium', 'Bark Shield (Medium)', 'rifts', 'armor', 6, 15000, '15,000-30,000 credits when sold, any size. Rarely sold; a gift of the tree. Rare except among warrior monks and Shinto priests.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 90, 'Millennium Tree bark shield: it can parry mega-damage magic weapons, the blows of vampires and supernatural beings, and dragon''s breath and other slow or predictable attacks; a successful parry absorbs the damage.', 'Rifts World Book 8: Japan p.32'),
('millennium-bark-shield-large', 'Bark Shield (Large)', 'rifts', 'armor', 12, 15000, '15,000-30,000 credits when sold, any size. Rarely sold; a gift of the tree. Rare except among warrior monks and Shinto priests.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 120, 'Millennium Tree bark shield: it can parry mega-damage magic weapons, the blows of vampires and supernatural beings, and dragon''s breath and other slow or predictable attacks; a successful parry absorbs the damage. The large shield covers three-quarters of the body and is -1 to parry.', 'Rifts World Book 8: Japan p.32'),
('millennium-leaf-body-armor', 'Leaf Body Armor', 'rifts', 'armor', 5, 50000, '50,000-100,000 credits when sold. Rarely sold; common among warrior monks, yamabushi and Shinto priests, rare elsewhere.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 60, 'Great Millennium Tree leaves worn as a poncho or cloak or cut into a fitted suit (a mega-damage blade is needed to cut them): typically 60 M.D.C., excellent mobility, no encumbrance, soft for generations. Holds 4D6 P.P.E. for a practitioner of magic. Magic energy attacks do one-third damage. +2 to save vs poison, toxins, gases and disease.', 'Rifts World Book 8: Japan p.32-33'),
('millennium-leaf-blanket-of-healing', 'Leaf: Blanket of Healing', 'rifts', 'magic', NULL, 90000, 'Leaves have sold for 90,000-150,000 credits; rare even among warrior monks, yamabushi and Shinto priests. The tree may give one to a trusted friend or champion of good.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A 4-6 ft Millennium Tree leaf laid over the sick or wounded: instantly negates poison, toxins and chemicals and heals 2D6 S.D.C. and 2D6 hit points (2D6 M.D.C. for a mega-damage creature), +30% to recover from coma, and hides the still patient as chameleon. It can also perform the tree''s restoration - reattach a severed limb or rouse the comatose - but the leaf then withers away.', 'Rifts World Book 8: Japan p.32'),
('elemental-shuriken-air', 'Elemental Shuriken: Air', 'rifts', 'weapon', NULL, 180000, '180,000-220,000 credits each; a set of all five 700,000 to one million. Very rare.', '2D6 M.D.; lightning bolt 1D4x10 M.D. (+3 to strike) three times a day', 1, 'thrown 1,000 ft; bolt 2,000 ft', NULL, NULL, NULL, NULL, NULL, 'One of the five Elemental Shuriken, enchanted throwing stars that return to the thrower''s hand. The air shuriken can also loose a lightning bolt three times a day.', 'Rifts World Book 8: Japan p.37'),
('elemental-shuriken-fire', 'Elemental Shuriken: Fire', 'rifts', 'weapon', NULL, 180000, '180,000-220,000 credits each; a set of all five 700,000 to one million. Very rare.', '3D6 M.D.; fire ball 5D6 M.D. (+3 to strike) four times a day', 1, 'thrown 600 ft; fire ball 1,000 ft', NULL, NULL, NULL, NULL, NULL, 'One of the five Elemental Shuriken, enchanted throwing stars that return to the thrower''s hand. The fire shuriken can also hurl a fire ball four times a day.', 'Rifts World Book 8: Japan p.37'),
('elemental-shuriken-water', 'Elemental Shuriken: Water', 'rifts', 'weapon', NULL, 180000, '180,000-220,000 credits each; a set of all five 700,000 to one million. Very rare.', '3D4 M.D.', 1, 'thrown 1,000 ft; 2,000 ft underwater', NULL, NULL, NULL, NULL, NULL, 'One of the five Elemental Shuriken, enchanted throwing stars that return to the thrower''s hand. The water shuriken casts calm storms, heal wounds and negate poisons/toxins, each twice a day.', 'Rifts World Book 8: Japan p.37'),
('elemental-shuriken-earth', 'Elemental Shuriken: Earth', 'rifts', 'weapon', NULL, 180000, '180,000-220,000 credits each; a set of all five 700,000 to one million. Very rare.', '4D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'One of the five Elemental Shuriken, enchanted throwing stars that return to the thrower''s hand. The earth shuriken casts invulnerability on its wielder three times a day, at 6th level.', 'Rifts World Book 8: Japan p.37'),
('elemental-shuriken-wood', 'Elemental Shuriken: Wood', 'rifts', 'weapon', NULL, 180000, '180,000-220,000 credits each; a set of all five 700,000 to one million. Very rare.', '2D4 M.D.; triple to vampires and creatures vulnerable to wood', 1, 'thrown 1,000 ft', NULL, NULL, NULL, NULL, NULL, 'One of the five Elemental Shuriken, enchanted throwing stars that return to the thrower''s hand. Once a day the wood shuriken summons an earth-tree elemental (200 M.D.C., +2 strike, parry and dodge, 3D6 M.D. punch) for 1D6 minutes.', 'Rifts World Book 8: Japan p.37'),
('tw-power-shuriken', 'TW Power Shuriken', 'rifts', 'weapon', NULL, 500, '500 credits.', '2D4+4 M.D. electrical, once', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A techno-wizard shuriken holding a single static charge that discharges on impact; afterwards it is an ordinary S.D.C. throwing star. The book prints the charge as 2D4+4 M.D.C. electrical damage, read here as M.D.', 'Rifts World Book 8: Japan p.37'),
('tw-fire-breathing-arquebus', 'TW Fire-Breathing Arquebus', 'rifts', 'weapon', NULL, 200000, 'At least 200,000 credits; rarely sold.', '5D6 M.D.', 1, '800 ft', NULL, 'three shots per melee', NULL, NULL, NULL, 'A techno-wizard matchlock that breathes fire instead of shot, drawing on an inexhaustible magic energy supply.', 'Rifts World Book 8: Japan p.37-38'),
('magic-powder-grenade-blinding', 'Magic Powder Grenade: Blinding', 'rifts', 'weapon', NULL, 500, '500 credits.', NULL, 0, '10 ft diameter', NULL, NULL, NULL, NULL, NULL, 'A Magic Powder Grenade: a clay or paper shell of enchanted powder. Prices vary from 10% less to 50% more (printed 38). Blinds everyone in the cloud for 1D6 minutes (-6 to strike, parry and dodge) unless they save vs ritual magic (16+).', 'Rifts World Book 8: Japan p.38'),
('magic-powder-grenade-confusion', 'Magic Powder Grenade: Confusion', 'rifts', 'weapon', NULL, 3000, '3,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Magic Powder Grenade: a clay or paper shell of enchanted powder. Prices vary from 10% less to 50% more (printed 38). Casts confusion, as a 4th level spell, on one to eight people in the cloud; save vs ritual magic.', 'Rifts World Book 8: Japan p.38'),
('magic-powder-grenade-minor-curse', 'Magic Powder Grenade: Minor Curse', 'rifts', 'weapon', NULL, 6000, '6,000 credits; one grenade per kind of curse.', NULL, 0, '20 ft', NULL, NULL, NULL, NULL, NULL, 'A Magic Powder Grenade: a clay or paper shell of enchanted powder. Prices vary from 10% less to 50% more (printed 38). Lays a 4th level minor curse on those in the cloud; save vs ritual magic.', 'Rifts World Book 8: Japan p.38'),
('magic-powder-grenade-magic-net', 'Magic Powder Grenade: Magic Net', 'rifts', 'weapon', NULL, 4000, '4,000 credits.', NULL, 0, '20 ft maximum', NULL, NULL, NULL, NULL, NULL, 'A Magic Powder Grenade: a clay or paper shell of enchanted powder. Prices vary from 10% less to 50% more (printed 38). Snares the nearest single target in a magic net.', 'Rifts World Book 8: Japan p.38'),
('singing-arrow-terror', 'Singing Arrow: Terror', 'rifts', 'weapon', NULL, 2000, '2,000 credits.', '1D4 S.D.C.', 0, 'fear radius 100 ft', NULL, NULL, NULL, NULL, NULL, 'A Singing Arrow (nari-kabura): its enchantment equals a 5th level spell, the save is 16 or higher, and it is spent when fired (printed 38). Casts fear on all within 100 ft; save vs horror factor 16.', 'Rifts World Book 8: Japan p.38'),
('singing-arrow-exorcism', 'Singing Arrow: Exorcism', 'rifts', 'weapon', NULL, 4000, '4,000 credits.', '1D4 S.D.C.', 0, '100 ft', NULL, NULL, NULL, NULL, NULL, 'A Singing Arrow (nari-kabura): its enchantment equals a 5th level spell, the save is 16 or higher, and it is spent when fired (printed 38). Spirits, oni and faerie folk must save vs magic (16+) or be stunned 1D4 rounds; a lesser possessing demon is expelled.', 'Rifts World Book 8: Japan p.38'),
('singing-arrow-enticing-beauty', 'Singing Arrow: Enticing Beauty', 'rifts', 'weapon', NULL, 3000, '3,000 credits.', '1D4 S.D.C.', 0, '100 ft', NULL, NULL, NULL, NULL, NULL, 'A Singing Arrow (nari-kabura): its enchantment equals a 5th level spell, the save is 16 or higher, and it is spent when fired (printed 38). Those who fail to save are entranced and cannot attack, then fight at -2 with no initiative for 1D6 rounds.', 'Rifts World Book 8: Japan p.38'),
('singing-arrow-agony', 'Singing Arrow: Agony', 'rifts', 'weapon', NULL, 6000, '6,000 credits.', '1D4 S.D.C.', 0, '100 ft (30.5 m)', NULL, NULL, NULL, NULL, NULL, 'A Singing Arrow (nari-kabura): its enchantment equals a 5th level spell, the save is 16 or higher, and it is spent when fired (printed 38). Casts agony on its target; save vs magic 16+.', 'Rifts World Book 8: Japan p.38'),
('tanto-of-hellish-poison', 'Tanto of Hellish Poison', 'rifts', 'weapon', NULL, 8000000, 'At least eight million credits.', '3D6 S.D.C.; 4D6 M.D. to supernatural beings and M.D.C. materials; poison adds 3D6', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'A tainted dagger, which many monks and priests refuse to use, whose poison (save vs poison 15+) costs a failing victim initiative and one attack for 1D6+2 hours, with -2 to combat, -15% to skills, 1D6 damage an hour and a risk of losing 1D4 P.E.', 'Rifts World Book 8: Japan p.38'),
('ten-thousand-strength-nunchakus', '"Ten-Thousand-Strength" Nunchakus', 'rifts', 'weapon', NULL, 500000, '500,000 credits.', '3D6 M.D. per strike', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Enchanted nunchakus that strike with mega-damage force and give their wielder one extra attack per melee.', 'Rifts World Book 8: Japan p.38'),
('whirlwind-naginata', 'Whirlwind Naginata', 'rifts', 'weapon', NULL, 5000000, 'Five million credits or more.', '3D6+6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'Art of Defense: parries automatically while the wielder makes no attacks. Whirlwind, four times a day for 5 minutes: the wielder flies at 60 mph and deflects arrows and thrown weapons.', 'Rifts World Book 8: Japan p.38-39'),
('zen-masters-bow-greater', 'Zen Master''s Bow (Greater)', 'rifts', 'weapon', NULL, 300000000, '300 million credits at least.', '2D6 S.D.C.; M.D. by P.P.E.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Zen Master''s Bow, for masters of kyudo; in other hands it is an ordinary bow (2D6 S.D.C., +1 to strike). Its five powers: +2 to strike; sense the invisible; 1 P.P.E. makes an arrow do M.D. (double to supernatural beings); 5 P.P.E. doubles the rate of fire; 10 P.P.E. a round lets arrows curve around cover. The greater bow has all five.', 'Rifts World Book 8: Japan p.39'),
('zen-masters-bow-lesser', 'Zen Master''s Bow (Lesser)', 'rifts', 'weapon', NULL, 40000000, '40 to 80 million credits.', '2D6 S.D.C.; M.D. by P.P.E.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Zen Master''s Bow, for masters of kyudo; in other hands it is an ordinary bow (2D6 S.D.C., +1 to strike). Its five powers: +2 to strike; sense the invisible; 1 P.P.E. makes an arrow do M.D. (double to supernatural beings); 5 P.P.E. doubles the rate of fire; 10 P.P.E. a round lets arrows curve around cover. The lesser bow has any two.', 'Rifts World Book 8: Japan p.39'),
('daisho-of-the-relentless-warrior', 'Daisho of the Relentless Warrior', 'rifts', 'weapon', NULL, NULL, 'Not priced individually; Greater Daisho sets could fetch in excess of 400 million credits (printed 39).', '1D6x10 M.D. each sword, always mega-damage', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'A Greater Daisho rune sword set, building on the qualities of the samurai''s mystic daisho (printed 44). Greater Daisho sets could fetch in excess of 400 million credits (printed 39). Principled or scrupulous wielders only. Relentless Strength, three times a day for 2 minutes per level: +10 supernatural P.S., hit points and S.D.C. doubled and turned to M.D.C., a green aura (horror factor 15). Heals 3D6+3 three times a day.', 'Rifts World Book 8: Japan p.39-40'),
('daisho-of-the-storm', 'Daisho of the Storm', 'rifts', 'weapon', NULL, NULL, 'Not priced individually; Greater Daisho sets could fetch in excess of 400 million credits (printed 39).', 'Katana 1D4x10 M.D. to supernatural beings, 3D6 to others; wakizashi 5D6 M.D. to supernatural beings, 3D6 to others', 1, 'melee; lightning 1,000 ft', NULL, NULL, NULL, NULL, NULL, 'A Greater Daisho rune sword set, building on the qualities of the samurai''s mystic daisho (printed 44). Greater Daisho sets could fetch in excess of 400 million credits (printed 39). Scrupulous wielders. Call of the Storm, three times a day for 1 minute per level: a 500 ft storm that each melee may gust at 100 mph, strike with lightning (4D6 M.D.), knock down vehicles and robots under two tons, or drench foes (-4 strike, parry, dodge and initiative for 1D4 rounds, sight 10 ft).', 'Rifts World Book 8: Japan p.40'),
('ghostly-katana-of-soul-slaying', 'Ghostly Katana of Soul Slaying', 'rifts', 'weapon', NULL, NULL, 'No price printed; only four exist.', '1D4x10 M.D. to supernatural beings, 2D4x10 to vampires and undead; 6D6 S.D.C. to mortals', 1, 'melee', NULL, NULL, NULL, NULL, NULL, 'A katana without wakizashi, one of only four. Its blade passes through armor, power armor and force fields (not robots or vehicles) and strikes the insubstantial; it senses evil within 30 ft plus 10 ft per level.', 'Rifts World Book 8: Japan p.40'),
('bottomless-purse-money', 'Bottomless Purse: Money', 'rifts', 'magic', NULL, 100000, 'The lesser purses sell for 100,000-200,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Bottomless Purse (kanebukoro): it works only for the one it was given to, and nothing taken from it can be hoarded (printed 40-41). Ten times a day it yields a handful of 2D4+6 coins worth 2D6 credits each.', 'Rifts World Book 8: Japan p.40-41'),
('bottomless-purse-food', 'Bottomless Purse: Food', 'rifts', 'magic', NULL, 100000, 'The lesser purses sell for 100,000-200,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Bottomless Purse (kanebukoro): it works only for the one it was given to, and nothing taken from it can be hoarded (printed 40-41). Four times a day a handful becomes one meal.', 'Rifts World Book 8: Japan p.40-41'),
('bottomless-purse-of-wishes', 'Bottomless Purse: Wishes', 'rifts', 'magic', NULL, 5000000, 'Five to ten million credits; extremely rare.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Bottomless Purse (kanebukoro): it works only for the one it was given to, and nothing taken from it can be hoarded (printed 40-41). Three times a day it produces a small ordinary item, or 1D6x100 credits; never rare, magic, energy or alien items.', 'Rifts World Book 8: Japan p.40-41'),
('fan-of-the-forest-wind', 'Fan of the Forest Wind', 'rifts', 'magic', NULL, 50000, '50,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Waved, it raises a whirlwind of leaves over 30 ft; attackers need a called shot at -5 to hit anyone inside.', 'Rifts World Book 8: Japan p.41'),
('hat-of-invisibility', 'Hat of Invisibility (Kakuregasa)', 'rifts', 'magic', NULL, 30000, '30,000-100,000 credits; rarely sold.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Six times a day its wearer turns invisible for up to an hour.', 'Rifts World Book 8: Japan p.41'),
('heavenly-speaking-flute', 'Heavenly Speaking Flute (Ame-no-nori-goto)', 'rifts', 'magic', NULL, 50000, '50,000-100,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Three songs, each three times a day for up to an hour: Heavenly Senses (see the invisible, ley lines within 5 miles, evil within 60 ft); Spiritual Comfort (an evil spirit that fails to save vs magic 14+ must flee; one that saves is halved while within 300 ft or in hearing of the music); Summoning or Banishing (save 16+, exorcism +20%). For good alignments; an unprincipled or aberrant demon fighter has a 50% chance.', 'Rifts World Book 8: Japan p.41'),
('holy-incense-burner', 'Holy Incense Burner', 'rifts', 'magic', NULL, 200000, 'At least 200,000 credits with 1D4 packages of each powder; more packages 1,200-1,800 each.', NULL, 0, '30 ft cloud', NULL, NULL, NULL, NULL, NULL, 'Its smoke bars the kind of being named by the powder burned - ghosts and spirits, the dead and undead, or oni and demons - unless it saves vs ritual magic 16+; one inside takes 1D6 a round and -2 to initiative, strike, parry and dodge.', 'Rifts World Book 8: Japan p.41-42'),
('lantern-of-protection', 'Lantern of Protection', 'rifts', 'magic', NULL, 50, '50-200 credits when sold by unscrupulous merchants or bandits; temples give 1D4 only to the worthy on a quest.', NULL, 0, '20 ft', NULL, NULL, NULL, 12, NULL, 'Fragile and flammable. It holds 24 hours of light, spent an hour per lighting. A supernatural being must save vs psionics to come within 20 ft, and one that does loses half its attacks and bonuses and cannot cast magic; all people within 20 ft get +3 to save against supernatural effects (not against magic or psionics from mortals or dragons). It does not affect dragons, immortals, or mortal priests and practitioners of magic.', 'Rifts World Book 8: Japan p.42'),
('living-kami-statue-tiny', 'Living Kami Statue (Tiny)', 'rifts', 'magic', NULL, 50000, '50,000 credits, plus 1D4x10% for beauty.', '1D4 M.D.; 1D4+1 with a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Living Kami Statue (Kiagan-Kuyo), animated by a ritual (35% +4% per level to find it) and a spend of P.P.E.; it obeys for 1 hour per level of the caster, but has a 65% chance to deactivate rather than act against its kami''s alignment. Add 1D4x10% to the price for beauty (printed 42). Tiny: 1D4x10 M.D.C., supernatural P.S. 6, +2 strike and parry, +6 dodge; 2 P.P.E. to activate.', 'Rifts World Book 8: Japan p.42'),
('living-kami-statue-small', 'Living Kami Statue (Small)', 'rifts', 'magic', NULL, 100000, '100,000 credits, plus 1D4x10% for beauty.', '1D6 M.D.; 2D4 with a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Living Kami Statue (Kiagan-Kuyo), animated by a ritual (35% +4% per level to find it) and a spend of P.P.E.; it obeys for 1 hour per level of the caster, but has a 65% chance to deactivate rather than act against its kami''s alignment. Add 1D4x10% to the price for beauty (printed 42). Small: 2D4x10 M.D.C., supernatural P.S. 12, +2 strike and parry, +4 dodge; 4 P.P.E. to activate.', 'Rifts World Book 8: Japan p.42'),
('living-kami-statue-human-sized', 'Living Kami Statue (Human-Sized)', 'rifts', 'magic', NULL, 200000, '200,000 credits, plus 1D4x10% for beauty.', '2D6 M.D. punch; 3D6 with a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Living Kami Statue (Kiagan-Kuyo), animated by a ritual (35% +4% per level to find it) and a spend of P.P.E.; it obeys for 1 hour per level of the caster, but has a 65% chance to deactivate rather than act against its kami''s alignment. Add 1D4x10% to the price for beauty (printed 42). Human-sized: 3D6x10 M.D.C., supernatural P.S. 20, +3 strike, parry and dodge; 10 P.P.E. to activate.', 'Rifts World Book 8: Japan p.42'),
('living-kami-statue-giant', 'Living Kami Statue (Giant)', 'rifts', 'magic', NULL, 500000, '500,000 credits, plus 1D4x10% for beauty.', 'By P.S.; +2D6 with a weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Living Kami Statue (Kiagan-Kuyo), animated by a ritual (35% +4% per level to find it) and a spend of P.P.E.; it obeys for 1 hour per level of the caster, but has a 65% chance to deactivate rather than act against its kami''s alignment. Add 1D4x10% to the price for beauty (printed 42). Giant: 1D4x100 M.D.C., supernatural P.S. 1D4x10+20, +2 strike and parry, +1 dodge; 20 P.P.E. to activate.', 'Rifts World Book 8: Japan p.42'),
('mirror-of-true-seeing', 'Mirror of True-Seeing', 'rifts', 'magic', NULL, 200000, '200,000-400,000 credits; rare.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Six times a day it shows the true shape, alignment, supernatural aura or disease of whoever it reflects.', 'Rifts World Book 8: Japan p.42'),
('powder-of-the-heavenly-winds', 'Powder of the Heavenly Winds (Kamikaze)', 'rifts', 'magic', NULL, 200000, '200,000-400,000 credits a container.', 'Gust 3D6 M.D. (+3 to strike) once per melee; 4D6 S.D.C. a minute to people, animals and property', 1, '400 ft area', NULL, NULL, NULL, NULL, NULL, 'One use: its user commands the winds at up to 200 mph for 1D6+2 minutes; robots under 15 tons are knocked down.', 'Rifts World Book 8: Japan p.42-43'),
('tattoos-of-strength', 'Tattoos of Strength', 'rifts', 'magic', NULL, 60000, 'Upwards of 60,000 credits; given only to Yakuza enforcers and allies.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Four times a day for an hour the tattooed become supernatural: M.D.C. equal to P.E. x3 and +6 supernatural P.S. While active they take double damage from weapons made to harm the supernatural, such as rune daisho and Millennium Tree wood.', 'Rifts World Book 8: Japan p.43');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'the 63 Japan magic gear rows are in' AS assertion, count(*) AS got, 63 AS want
  FROM gear WHERE slug IN ('wand-of-the-animal', 'wand-of-deception', 'wand-of-divination', 'wand-of-dowsing', 'wand-of-knowledge', 'wand-of-life', 'wand-of-power', 'wand-of-seeing', 'sohei-staff-of-defense', 'staff-of-the-earth', 'staff-of-the-hunter', 'staff-of-life', 'staff-of-prosperity', 'staff-of-purity', 'staff-of-the-serpent', 'staff-of-the-wind', 'corrupted-millennium-wand-or-staff', 'millennium-vampire-slaying-javelin', 'millennium-throwing-stick', 'millennium-bark-body-armor', 'millennium-bark-shield-small', 'millennium-bark-shield-medium', 'millennium-bark-shield-large', 'millennium-leaf-body-armor', 'millennium-leaf-blanket-of-healing', 'elemental-shuriken-air', 'elemental-shuriken-fire', 'elemental-shuriken-water', 'elemental-shuriken-earth', 'elemental-shuriken-wood', 'tw-power-shuriken', 'tw-fire-breathing-arquebus', 'magic-powder-grenade-blinding', 'magic-powder-grenade-confusion', 'magic-powder-grenade-minor-curse', 'magic-powder-grenade-magic-net', 'singing-arrow-terror', 'singing-arrow-exorcism', 'singing-arrow-enticing-beauty', 'singing-arrow-agony', 'tanto-of-hellish-poison', 'ten-thousand-strength-nunchakus', 'whirlwind-naginata', 'zen-masters-bow-greater', 'zen-masters-bow-lesser', 'daisho-of-the-relentless-warrior', 'daisho-of-the-storm', 'ghostly-katana-of-soul-slaying', 'bottomless-purse-money', 'bottomless-purse-food', 'bottomless-purse-of-wishes', 'fan-of-the-forest-wind', 'hat-of-invisibility', 'heavenly-speaking-flute', 'holy-incense-burner', 'lantern-of-protection', 'living-kami-statue-tiny', 'living-kami-statue-small', 'living-kami-statue-human-sized', 'living-kami-statue-giant', 'mirror-of-true-seeing', 'powder-of-the-heavenly-winds', 'tattoos-of-strength') AND source_book LIKE 'Rifts World Book 8: Japan p.%';

